Sdb* process_verneed_section(ELFOBJ *bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Sdb *sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    void *data = elf_getdata(bin, shdr, &sz);
    if (!data) {
        sdb_free(sdb);
        return NULL;
    }

    Elf_(Verneed) *verneed = data;
    while ((size_t)((uintptr_t)verneed - (uintptr_t)data) < sz) {
        for (int j = 0; j < verneed->vn_cnt; j++) {
            Elf_(Verneed_entry) *vna = &verneed->vna[j];
            const char *version_name = sdb_get(bin->sym, vna->vna_name, 0);
            if (version_name) {
                sdb_num_set(sdb, version_name, 1, 0);
            }
        }

        size_t offset = sizeof(Elf_(Verneed)) + sizeof(Elf_(Verneed_entry)) * verneed->vn_cnt;
        verneed = (Elf_(Verneed)*)((uintptr_t)verneed + offset);
    }

    return sdb;
}

Sdb* sdb_from_verneed(ELFOBJ *bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Elf_(Addr) data_addr = shdr->sh_offset;
    size_t data_size = shdr->sh_size;
    Elf_(Verneed)* verneed = (Elf_(Verneed)*)elf_getdata(bin, data_addr, data_size);
    if (!verneed) {
        return NULL;
    }

    Sdb *sdb = sdb_new0();
    if (!sdb) {
        free(verneed);
        return NULL;
    }

    Elf_(Verneed)* entry = verneed;
    while ((size_t)((Elf_(Byte)*)entry - (Elf_(Byte)*)verneed) < data_size) {
        for (int i = 0; i < entry->vn_cnt; i++) {
            Elf_(Verneedaux)* aux = (Elf_(Verneedaux)*)((Elf_(Byte)*)entry + entry->vn_aux);
            const char* name = elf_strptr(bin, shdr->sh_link, aux->vna_name);
            char key[256];
            snprintf(key, sizeof(key), "version.%s", name);
            sdb_num_set(sdb, key, aux->vna_hash, 0);
            entry = (Elf_(Verneed*)((Elf_(Byte)*)entry + entry->vn_next));
        }
    }

    free(verneed);
    return sdb;
}

#include <stdlib.h>
#include <string.h>

Sdb* process_verneed_section(ELFOBJ* bin, Elf_Shdr* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Sdb* sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    void* verneed_data = elf_get_section_data(bin, shdr);
    if (!verneed_data) {
        sdb_free(sdb);
        return NULL;
    }

    Elf_Verneed* vn = verneed_data;
    while ((char*)vn < (char*)verneed_data + sz) {
        for (int i = 0; i < vn->vn_cnt; i++) {
            Elf_Vernaux* vna = (Elf_Vernaux*)((char*)vn + sizeof(Elf_Verneed) + i * sizeof(Elf_Vernaux));
            char* version_name = sdb_get_version_string(bin, vna->vna_name);
            if (version_name) {
                sdb_num_put(sdb, version_name, vna->vna_hash);
            }
        }
        vn = (Elf_Verneed*)((char*)vn + vn->vn_next);
    }

    return sdb;
}

Sdb *process_verneed_section(ELFOBJ *bin, Elf_Shdr *shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Sdb *sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    guint8 *data = elf_get_section_data(bin, shdr);
    if (!data) {
        sdb_free(sdb);
        return NULL;
    }

    Elf_Verneed *verneed = (Elf_Verneed *)data;
    while (verneed && verneed->vn_cnt > 0) {
        for (int i = 0; i < verneed->vn_cnt; i++) {
            Elf_Vernaux *vernaux = &verneed->vnaux[i];
            const char *version_name = elf_strptr(bin, shdr->sh_link, vernaux->vna_name);
            if (!version_name) {
                sdb_free(sdb);
                return NULL;
            }

            char key[256];
            snprintf(key, sizeof(key), "version.%s", version_name);
            sdb_num_set(sdb, key, 1, 0);

            // Handle auxiliary entries if necessary
            if (vernaux->vna_next > 0) {
                Elf_Vernaux *next_vernaux = (Elf_Vernaux *)((guint8 *)vernaux + vernaux->vna_next);
                while (next_vernaux) {
                    const char *aux_name = elf_strptr(bin, shdr->sh_link, next_vernaux->vna_name);
                    if (!aux_name) {
                        sdb_free(sdb);
                        return NULL;
                    }

                    snprintf(key, sizeof(key), "version.aux.%s", aux_name);
                    sdb_num_set(sdb, key, 1, 0);

                    next_vernaux = (Elf_Vernaux *)((guint8 *)next_vernaux + next_vernaux->vna_next);
                }
            }
        }

        verneed = (Elf_Verneed *)((guint8 *)verneed + verneed->vn_next);
    }

    return sdb;
}

Sdb* parse_verneed_section(ELFOBJ* bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Sdb* sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    void* verneed_data = elf_read_section(bin, shdr, sz);
    if (!verneed_data) {
        sdb_free(sdb);
        return NULL;
    }

    // Assume Verneed entries are in a known format and can be parsed
    Elf_(Verneed)* verneed = verneed_data;
    for (size_t i = 0; i < shdr->sh_size / sizeof(Elf_(Verneed)); i++) {
        Elf_(Verneed) entry = verneed[i];
        // Process each entry and its aux entries
        for (int j = 0; j < entry.vn_cnt; j++) {
            Elf_(Verneed_aux)* aux = (Elf_(Verneed_aux)*)(verneed_data + entry.vn_aux);
            char* version_name = elf_get_string(bin, shdr->sh_link, aux->vna_name);
            if (!version_name) {
                free(verneed_data);
                sdb_free(sdb);
                return NULL;
            }
            sdb_num_set(sdb, version_name, (ut64)1, 0);
        }
    }

    free(verneed_data);
    return sdb;
}
